H.background();
const w = H.W, h = H.H;
const mant = P.mantissa;
const exp = Math.round(P.exp);
const value = mant * Math.pow(10, exp);
H.text("Scientific notation:  value = m × 10^n", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + mant.toFixed(2) + ",   n = " + exp + "   →   " + mant.toFixed(2) + " × 10^" + exp, 24, 52, { color: H.colors.sub, size: 13 });
// Build the expanded decimal string by literally shifting the point n places.
const sign = value < 0 ? "-" : "";
const av = Math.abs(value);
let expanded;
if (av === 0) {
  expanded = "0";
} else if (av >= 1e-6 && av < 1e12) {
  // round to kill float fuzz, then trim trailing zeros
  let s = av.toFixed(Math.max(0, 6 - exp));
  if (s.indexOf(".") >= 0) s = s.replace(/0+$/, "").replace(/\.$/, "");
  expanded = sign + s;
} else {
  expanded = sign + av.toExponential(3);
}
// big readout of the actual number, centered
H.text("= " + expanded, w * 0.5, h * 0.32, { color: H.colors.good, size: 30, weight: 700, align: "center" });
